window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ddf4d7df5df6570"]={"versions": [{"id": "FIG-2ddf4d7df5df6570", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Einzelschritts „Write Counter“ innerhalb des Schutzes von E2E Profile 22 (<code>E2E_P22Protect()</code>) gemäß AUTOSAR E2E-Protokollspezifikation. Das Diagramm spezifiziert die Serialisierung des Alive-Counters in das Nutzdatenarray.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionen/Zustände:</strong></li>\n<li>Initialer Startknoten (Initial Node)</li>\n<li>Aktion <code>Counter = State-&gt;Counter</code></li>\n<li>Aktion <code>Copy lower 4 bits of State-&gt;Counter to data array at bit position Config-&gt;Offset + 8</code></li>\n<li>Finaler Endknoten (Activity Final Node)</li>\n<li><strong>Kontext-Symbol:</strong></li>\n<li><code>E2E_P22Protect()</code> als übergeordneter Funktionskontext</li>\n<li><strong>Kommentare/Notizen:</strong></li>\n<li>Notiz zu Aktion 1: <code>Store value of State-&gt;Counter in local variable to be also used in CRC calculation</code></li>\n<li>Notiz zu Aktion 2: <code>Byte position in data array can be obtained by: DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code></li>\n<li><strong>Variablen und Datenstrukturen:</strong></li>\n<li><code>State-&gt;Counter</code>: Counter-Feld der Zustandsstruktur</li>\n<li><code>Counter</code>: Lokale Variable für Zwischenspeicherung und nachfolgende CRC-Berechnung</li>\n<li><code>Config-&gt;Offset</code>: Bit-Offset in der Konfigurationsstruktur</li>\n<li><code>DataPtr</code>: Byte-Zeiger auf das Nutzdatenarray</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Initialknoten.</li>\n<li>Speicherung des aktuellen Zählerwerts <code>State-&gt;Counter</code> in der lokalen Variablen <code>Counter</code>.</li>\n<li>Extraktion der unteren 4 Bits (<code>lower 4 bits</code>) von <code>State-&gt;Counter</code> und bitgenaue Übertragung in das Datenarray an der Bit-Position <code>Config-&gt;Offset + 8</code> (entsprechend Byte <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>).</li>\n<li>Erreichen des Aktivitätsendknotens.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Pflicht:</strong> Die unteren 4 Bits des Statuszählers müssen exakt ab Offset + 8 Bits serialisiert werden. Die oberen 4 Bits des Zählers (falls vorhanden) fließen nicht an diese Datenposition ein.</li>\n<li><strong>Implementierungshinweis:</strong> Durch die Division durch 8 (<code>&gt;&gt; 3</code>) plus 1 Byte Offset wird die Byte-Adresse des Zählers im Serialisierungspuffer ermittelt.</li>\n<li><strong>Konsistenz:</strong> Die lokale Variable <code>Counter</code> sichert den Zählerstand snapshot-artig für die spätere CRC-Berechnung ab, um Inkonsistenzen bei Zustandsänderungen zu vermeiden.</li>\n</ul>"}, {"id": "FIG-ae43f7a15d47bc13", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Schritts „Write Counter“ für die Funktionen <code>E2E_P22Protect()</code> und <code>E2E_P22Forward()</code> des AUTOSAR E2E-Profils 22. Das Diagramm modelliert die bitgenaue Platzierung des Zählerwerts in das Nutzdatenarray.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionen/Zustände:</strong></li>\n<li>Initialer Startknoten (Initial Node)</li>\n<li>Aktion <code>Counter = State-&gt;Counter</code></li>\n<li>Aktion <code>Copy lower 4 bits of State-&gt;Counter to data array at bit position Config-&gt;Offset + 8</code></li>\n<li>Finaler Endknoten (Activity Final Node)</li>\n<li><strong>Kontext-Symbole:</strong></li>\n<li><code>E2E_P22Protect()</code></li>\n<li><code>E2E_P22Forward()</code></li>\n<li><strong>Kommentare/Notizen:</strong></li>\n<li>Notiz zu Aktion 1: <code>Store value of State-&gt;Counter in local variable to be also used in CRC calculation</code></li>\n<li>Notiz zu Aktion 2: <code>Byte position in data array can be obtained by: DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code></li>\n<li><strong>Variablen und Datenstrukturen:</strong></li>\n<li><code>State-&gt;Counter</code>: Zählerstand der E2E-Zustandsstruktur</li>\n<li><code>Counter</code>: Lokale Variable für Zwischenspeicherung und CRC-Berechnung</li>\n<li><code>Config-&gt;Offset</code>: Bit-Offset-Konfiguration</li>\n<li><code>DataPtr</code>: Zeiger auf das zu schützende bzw. weiterzuleitende Datenarray</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Initialknoten.</li>\n<li>Speicherung des aktuellen Zählerwerts <code>State-&gt;Counter</code> in der lokalen Variablen <code>Counter</code>.</li>\n<li>Extraktion der unteren 4 Bits (<code>lower 4 bits</code>) von <code>State-&gt;Counter</code> und bitgenaue Übertragung in das Datenarray an der Bit-Position <code>Config-&gt;Offset + 8</code> (entsprechend Byte <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>).</li>\n<li>Erreichen des Aktivitätsendknotens.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Pflicht:</strong> Die Spezifikation für das Schreiben des Counters gilt gleichermaßen für Schutz- (<code>E2E_P22Protect()</code>) und Weiterleitungsoperationen (<code>E2E_P22Forward()</code>). Die unteren 4 Bits von <code>State-&gt;Counter</code> müssen an Bit-Position <code>Config-&gt;Offset + 8</code> abgelegt werden.</li>\n<li><strong>Implementierungshinweis:</strong> Die Byte-Position im Puffer errechnet sich über <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>.</li>\n<li><strong>Konsistenz:</strong> Der Zählerwert wird für die Berechnung der Prüfsumme in einer lokalen Variablen <code>Counter</code> gepuffert.</li>\n</ul>"}, {"id": "FIG-3a473143ce5e5496", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Schritts „Write Counter“ für die Funktionen <code>E2E_P22Protect()</code> und <code>E2E_P22Forward()</code> des AUTOSAR E2E-Profils 22. Das Diagramm modelliert die bitgenaue Platzierung des Zählerwerts in das Nutzdatenarray.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionen/Zustände:</strong></li>\n<li>Initialer Startknoten (Initial Node)</li>\n<li>Aktion <code>Counter = State-&gt;Counter</code></li>\n<li>Aktion <code>Copy lower 4 bits of State-&gt;Counter to data array at bit position Config-&gt;Offset + 8</code></li>\n<li>Finaler Endknoten (Activity Final Node)</li>\n<li><strong>Kontext-Symbole:</strong></li>\n<li><code>E2E_P22Protect()</code></li>\n<li><code>E2E_P22Forward()</code></li>\n<li><strong>Kommentare/Notizen:</strong></li>\n<li>Notiz zu Aktion 1: <code>Store value of State-&gt;Counter in local variable to be also used in CRC calculation</code></li>\n<li>Notiz zu Aktion 2: <code>Byte position in data array can be obtained by: DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code></li>\n<li><strong>Variablen und Datenstrukturen:</strong></li>\n<li><code>State-&gt;Counter</code>: Zählerstand der E2E-Zustandsstruktur</li>\n<li><code>Counter</code>: Lokale Variable für Zwischenspeicherung und CRC-Berechnung</li>\n<li><code>Config-&gt;Offset</code>: Bit-Offset-Konfiguration</li>\n<li><code>DataPtr</code>: Zeiger auf das zu schützende bzw. weiterzuleitende Datenarray</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Initialknoten.</li>\n<li>Speicherung des aktuellen Zählerwerts <code>State-&gt;Counter</code> in der lokalen Variablen <code>Counter</code>.</li>\n<li>Extraktion der unteren 4 Bits (<code>lower 4 bits</code>) von <code>State-&gt;Counter</code> und bitgenaue Übertragung in das Datenarray an der Bit-Position <code>Config-&gt;Offset + 8</code> (entsprechend Byte <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>).</li>\n<li>Erreichen des Aktivitätsendknotens.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Pflicht:</strong> Die Spezifikation für das Schreiben des Counters gilt gleichermaßen für Schutz- (<code>E2E_P22Protect()</code>) und Weiterleitungsoperationen (<code>E2E_P22Forward()</code>). Die unteren 4 Bits von <code>State-&gt;Counter</code> müssen an Bit-Position <code>Config-&gt;Offset + 8</code> abgelegt werden.</li>\n<li><strong>Implementierungshinweis:</strong> Die Byte-Position im Puffer errechnet sich über <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>.</li>\n<li><strong>Konsistenz:</strong> Der Zählerwert wird für die Berechnung der Prüfsumme in einer lokalen Variablen <code>Counter</code> gepuffert.</li>\n</ul>"}, {"id": "FIG-764fdf01367eca7f", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Schritts „Write Counter“ für die Funktionen <code>E2E_P22Protect()</code> und <code>E2E_P22Forward()</code> des AUTOSAR E2E-Profils 22. Das Diagramm modelliert die bitgenaue Platzierung des Zählerwerts in das Nutzdatenarray.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktionen/Zustände:</strong></li>\n<li>Initialer Startknoten (Initial Node)</li>\n<li>Aktion <code>Counter = State-&gt;Counter</code></li>\n<li>Aktion <code>Copy lower 4 bits of State-&gt;Counter to data array at bit position Config-&gt;Offset + 8</code></li>\n<li>Finaler Endknoten (Activity Final Node)</li>\n<li><strong>Kontext-Symbole:</strong></li>\n<li><code>E2E_P22Protect()</code></li>\n<li><code>E2E_P22Forward()</code></li>\n<li><strong>Kommentare/Notizen:</strong></li>\n<li>Notiz zu Aktion 1: <code>Store value of State-&gt;Counter in local variable to be also used in CRC calculation</code></li>\n<li>Notiz zu Aktion 2: <code>Byte position in data array can be obtained by: DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code></li>\n<li><strong>Variablen und Datenstrukturen:</strong></li>\n<li><code>State-&gt;Counter</code>: Zählerstand der E2E-Zustandsstruktur</li>\n<li><code>Counter</code>: Lokale Variable für Zwischenspeicherung und CRC-Berechnung</li>\n<li><code>Config-&gt;Offset</code>: Bit-Offset-Konfiguration</li>\n<li><code>DataPtr</code>: Zeiger auf das zu schützende bzw. weiterzuleitende Datenarray</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eintritt über den Initialknoten.</li>\n<li>Speicherung des aktuellen Zählerwerts <code>State-&gt;Counter</code> in der lokalen Variablen <code>Counter</code>.</li>\n<li>Extraktion der unteren 4 Bits (<code>lower 4 bits</code>) von <code>State-&gt;Counter</code> und bitgenaue Übertragung in das Datenarray an der Bit-Position <code>Config-&gt;Offset + 8</code> (entsprechend Byte <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>).</li>\n<li>Erreichen des Aktivitätsendknotens.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Pflicht:</strong> Die Spezifikation für das Schreiben des Counters gilt gleichermaßen für Schutz- (<code>E2E_P22Protect()</code>) und Weiterleitungsoperationen (<code>E2E_P22Forward()</code>). Die unteren 4 Bits von <code>State-&gt;Counter</code> müssen an Bit-Position <code>Config-&gt;Offset + 8</code> abgelegt werden.</li>\n<li><strong>Implementierungshinweis:</strong> Die Byte-Position im Puffer errechnet sich über <code>DataPtr[(Config-&gt;Offset &gt;&gt; 3) + 1]</code>.</li>\n<li><strong>Konsistenz:</strong> Der Zählerwert wird für die Berechnung der Prüfsumme in einer lokalen Variablen <code>Counter</code> gepuffert.</li>\n</ul>"}], "trans": [{"from": "FIG-2ddf4d7df5df6570", "to": "FIG-ae43f7a15d47bc13", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Aufrufkontext / Scope: Das Aktivitätsdiagramm erhält oben links ein zusätzliches Invocation-Symbol für <code>E2E_P22Forward()</code>, wodurch die Teilspezifikation zum Schreiben des Counters auch für die Forward-Funktion von E2E Profile 22 gilt.</li>\n</ul>"}, {"from": "FIG-ae43f7a15d47bc13", "to": "FIG-3a473143ce5e5496", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3a473143ce5e5496", "to": "FIG-764fdf01367eca7f", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
